/* PlayStation DNA — console blue on studio white, iconic shapes */
.theme-playstation-dna {
  --bg: oklch(0.956 0.005 275.0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.926 0.011 274.9);
  --fg: oklch(0.241 0.009 285.7);
  --fg-muted: oklch(0.485 0 0);
  --accent: oklch(0.548 0.172 253.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.371 0.158 260.7);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.577 0.215 27.3);
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Encode Sans", sans-serif;
  --font-body: "Encode Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-playstation-dna h1,
.theme-playstation-dna h2,
.theme-playstation-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-playstation-dna { --font-ui: var(--font-display); }
.theme-playstation-dna h1 { font-weight: 700; }
.theme-playstation-dna h2::before { content: "△ ○ ✕ □ "; color: var(--accent); font-size: 0.55em; letter-spacing: 0.2em; vertical-align: middle; }

/* depth */
.theme-playstation-dna { background-image: radial-gradient(oklch(0.241 0.009 285.7 / 5%) 1px, transparent 1px); background-size: 22px 22px; }
.theme-playstation-dna thead th { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.1em; color: var(--fg-muted); border-bottom: 2px solid var(--accent); }
.theme-playstation-dna tbody td { border-bottom: 1px solid var(--line); }
.theme-playstation-dna tbody tr:hover td { background: color-mix(in oklab, var(--accent) 7%, transparent); }
.theme-playstation-dna a { color: var(--accent); text-underline-offset: 3px; text-decoration-thickness: 2px; text-decoration-color: color-mix(in oklab, var(--accent) 35%, transparent); }
.theme-playstation-dna a:hover { text-decoration-color: var(--accent); }
.theme-playstation-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-playstation-dna input, .theme-playstation-dna select { border-radius: var(--radius-pill); }
.theme-playstation-dna input:focus-visible, .theme-playstation-dna select:focus-visible, .theme-playstation-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--accent) 30%, transparent); }
.theme-playstation-dna kbd { font-family: var(--font-mono); font-size: 0.78em; padding: 0.12em 0.6em; border-radius: var(--radius-pill); background: var(--surface); border: 1px solid var(--line); box-shadow: 0 2px 0 var(--line); }
.theme-playstation-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-playstation-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-playstation-dna ::-webkit-scrollbar-thumb { background: color-mix(in oklab, var(--accent) 55%, var(--surface-2)); border-radius: 999px; }
.theme-playstation-dna .label-caps { color: var(--accent-2); font-weight: 700; }
.theme-playstation-dna .themed-border { border-color: color-mix(in oklab, var(--accent) 40%, var(--line)); }
.theme-playstation-dna button:active { transform: translateY(1px); }

/* alt mode: console dark — PS5 midnight blue, DualSense glow */
.theme-playstation-dna.alt-mode {
  --bg: oklch(0.165 0.035 265.0);
  --surface: oklch(0.205 0.040 264.0);
  --surface-2: oklch(0.250 0.045 263.0);
  --fg: oklch(0.960 0.008 260.0);
  --fg-muted: oklch(0.720 0.020 258.0);
  --accent: oklch(0.664 0.140 250.0);
  --accent-2: oklch(0.810 0.090 248.0);
  --line: oklch(1 0 0 / 16%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: radial-gradient(oklch(1 0 0 / 4%) 1px, transparent 1px);
  background-size: 22px 22px;
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
